// remen.uz category hierarchy (data/categories.json, generated by scripts/build-data.mjs).
import categoriesJson from "@/data/categories.json";
import type { Lang } from "./lang";

export type Category = {
  id: number;
  slug: string;
  parentId: number | null;
  order: number;
  name: string;
  nameUz: string | null;
  count: number;
};

export const CATEGORIES = categoriesJson as Category[];

/** Root ids on remen.uz: the product catalog and the industries ("Сферы деятельности") tree. */
export const CATALOG_ROOT = 1;
export const SPHERES_ROOT = 2;

const byId = new Map(CATEGORIES.map((c) => [c.id, c]));
const bySlug = new Map(CATEGORIES.map((c) => [c.slug, c]));

export const getCategory = (id: number) => byId.get(id);
export const getCategoryBySlug = (slug: string) => bySlug.get(slug);

export const childrenOf = (id: number) =>
  CATEGORIES.filter((c) => c.parentId === id).sort((a, b) => a.order - b.order || a.id - b.id);

/** Ancestors from the top section down to (and including) the category, without the two roots. */
export function pathOf(id: number): Category[] {
  const out: Category[] = [];
  for (let c = byId.get(id); c && c.parentId !== null; c = byId.get(c.parentId)) out.unshift(c);
  return out;
}

export const catName = (c: Category, lang: Lang) => (lang === "uz" && c.nameUz ? c.nameUz : c.name).trim();

/** Short label for a category's glass drop, e.g. "HTD · STD · RPP" or "PJ · PK". */
export function catCode(c: Category): string {
  // Profile/type subcategories give short codes; descriptive ones ("Классические ремни") don't fit a drop.
  const kids = childrenOf(c.id).filter((k) => /^(Тип|Профиль)\s*-/.test(k.name));
  if (kids.length) {
    const codes = [...new Set(kids.map((k) => k.name.replace(/^(Тип|Профиль)\s*-\s*/, "").replace(/\s*\(.*\)$/, "").split("/")[0].trim()))];
    return codes.slice(0, 3).join(" · ") + (codes.length > 3 ? " …" : "");
  }
  const words = c.name.trim().split(/\s+/);
  return (words.length > 1 ? words[0][0] + words[1][0] : words[0].slice(0, 3)).toUpperCase();
}

